Q: Check for nil and nil interface in Go A: <pre><code>func IsNilish(val interface{}) bool {
    if val == nil {
        return true
    }

    v := reflect.ValueOf(val)
    k := v.Kind()
    switch k {
    case reflect.Chan, reflect.Func, reflect.Map, reflect.Pointer,
        reflect.UnsafePointer, reflect.Interface, reflect.Slice:
        return v.IsNil()
    }

    return false
}
</code></pre>
